import { LIMITS } from "@alloo/shared/policy";
import type { FunctionReturnType } from "convex/server";
// @generated by:gauntlet run:alloo-production
import { convexTest } from "convex-test";
import { afterEach, expect, it, vi } from "vitest";
import { setupUsers } from "../test-support";
import { api } from "./_generated/api";
import schema from "./schema";

const modules = import.meta.glob("./**/*.ts");
const setup = () => setupUsers(modules);
afterEach(() => vi.useRealTimers());
it("T-PROD-BLOCK bounds stored blocks while always allowing unblock", async () => {
  const { t, a, ids } = await setup();
  await t.run(async (ctx) => {
    for (let i = 0; i < LIMITS.blocks; i++) {
      const targetId = await ctx.db.insert("users", {});
      await ctx.db.insert("blocks", { userId: ids[0], targetId });
    }
  });
  await expect(a.mutation(api.accounts.block, { targetId: ids[1], blocked: true })).rejects.toThrow(
    "BLOCK_LIMIT",
  );
  const old = await t.run((ctx) => ctx.db.query("blocks").first());
  if (!old) throw new Error("Fixture missing");
  await a.mutation(api.accounts.block, { targetId: old.targetId, blocked: false });
  await a.mutation(api.accounts.block, { targetId: ids[1], blocked: true });
});
it("T-PROD-SESSION another caller tab cannot cancel a ringing call", async () => {
  const { a, ids } = await setup();
  const conversationId = await a.mutation(api.conversations.createDM, { targetId: ids[1] });
  const id = await a.mutation(api.calls.start, { conversationId, kind: "audio", session: "owner" });
  await expect(a.mutation(api.calls.hangup, { id, session: "other" })).rejects.toThrow(
    "OTHER_SESSION",
  );
  await a.mutation(api.calls.hangup, { id, session: "owner" });
});
it("T-PROD-BLOCK supports the full 100-member group capacity", async () => {
  const { t, a, ids } = await setup();
  const more = await t.run(async (ctx) => {
    const added = [];
    for (let i = 0; i < 97; i++) {
      const userId = await ctx.db.insert("users", {});
      await ctx.db.insert("profiles", {
        userId,
        name: `Member ${i}`,
        username: `member_${i}`,
        bio: "",
      });
      added.push(userId);
    }
    return added;
  });
  const id = await a.mutation(api.conversations.createGroup, {
    title: "Capacity",
    userIds: [...ids.slice(1), ...more],
  });
  expect((await a.query(api.conversations.details, { id }))?.members).toHaveLength(100);
});
it("T-PROD-DELETE ends media and revokes sidebar access before scheduled cleanup", async () => {
  vi.useFakeTimers();
  const { t, a, b, ids } = await setup();
  const conversationId = await a.mutation(api.conversations.createDM, { targetId: ids[1] });
  const id = await a.mutation(api.calls.start, {
    conversationId,
    kind: "audio",
    session: "caller-tab",
  });
  await b.mutation(api.calls.accept, { id, session: "recipient-tab" });
  await a.mutation(api.accounts.remove, { confirmation: "SUPPRIMER" });
  expect((await b.query(api.calls.get, { id }))?.state).toBe("ended");
  expect(
    (await a.query(api.conversations.list, { paginationOpts: { cursor: null, numItems: 20 } }))
      .page,
  ).toEqual([]);
  await t.finishAllScheduledFunctions(() => vi.runAllTimers());
});
