it("T-PROD-SESSION call views do not disclose either tab ownership key", async () => {
  const { a, b, ids } = await setup();
  const conversationId = await a.mutation(api.conversations.createDM, { targetId: ids[1] });
  const id = await a.mutation(api.calls.start, {
    conversationId,
    kind: "audio",
    session: "caller-tab",
  });
  await b.mutation(api.calls.accept, { id, session: "recipient-tab" });
  for (const client of [a, b])
    for (const view of [
      await client.query(api.calls.current, {}),
      await client.query(api.calls.get, { id }),
    ]) {
      expect(view).not.toHaveProperty("callerSession");
      expect(view).not.toHaveProperty("acceptedSession");
    }
});
it("T-PROD-RETRY refuses reusing an operation for a different reply", async () => {
  const { a, ids } = await setup();
  const id = await a.mutation(api.conversations.createDM, { targetId: ids[1] });
  const replyId = await a.mutation(api.messages.send, {
    id,
    body: "first",
    operationId: "first-message",
  });
  const args = { id, body: "same text", operationId: "second-message" };
  await a.mutation(api.messages.send, args);
  await expect(a.mutation(api.messages.send, { ...args, replyId })).rejects.toThrow("CONFLICT");
});

it("T-FINAL-DELETE deletion before onboarding immediately prevents profile recreation", async () => {
  vi.useFakeTimers();
  const t = convexTest(schema, modules);
  const id = await t.run((ctx) => ctx.db.insert("users", { name: "Unfinished" }));
  const client = t.withIdentity({ subject: id });
  await client.mutation(api.accounts.remove, { confirmation: "SUPPRIMER" });
  await expect(
    client.mutation(api.profiles.save, { name: "Revived", username: "revived", bio: "" }),
  ).rejects.toThrow("ACCOUNT_DELETED");
});

it("T-FINAL-BUDGET paginates large histories without losing conversations or exceeding the aggregate batch", async () => {
  const { t, a, ids } = await setup();
  const total = 17;
  await t.run(async (ctx) => {
    for (let i = 0; i < total; i++) {
      const id = await ctx.db.insert("conversations", {
        kind: "group",
        title: "Large history",
        updatedAt: i,
      });
      await ctx.db.insert("members", {
        conversationId: id,
        userId: ids[0],
        role: "admin",
        readAt: 0,
        updatedAt: i,
      });
      for (let j = 0; j < 100; j++)
        await ctx.db.insert("messages", {
          conversationId: id,
          userId: ids[0],
          body: "界".repeat(LIMITS.message),
          operationId: `fixture-${i}-${j}`,
          kind: "text",
          pinned: false,
        });
    }
  });
  const seen = new Set<string>();
  let cursor: string | null = null;
  do {
    const result: FunctionReturnType<typeof api.conversations.list> = await a.query(
      api.conversations.list,
      {
        paginationOpts: { numItems: 30, cursor },
      },
    );
    expect(result.page.length).toBeLessThanOrEqual(LIMITS.conversationPage);
    expect(
      result.page.length * 100 * new TextEncoder().encode("界".repeat(LIMITS.message)).length,
    ).toBeLessThan(12 * 1024 * 1024);
    for (const row of result.page) {
      expect(seen.has(row._id)).toBe(false);
      seen.add(row._id);
    }
    cursor = result.isDone ? null : result.continueCursor;
  } while (cursor);
  expect(seen.size).toBe(total);
});

it("T-FINAL-REACTIVE mounted settings and call queries tolerate remote account deletion", async () => {
  vi.useFakeTimers();
  const { a, b, ids } = await setup();
  const id = await a.mutation(api.conversations.createDM, { targetId: ids[1] });
  const callId = await a.mutation(api.calls.start, {
    conversationId: id,
    kind: "audio",
    session: "owner-session",
  });
  await a.mutation(api.accounts.remove, { confirmation: "SUPPRIMER" });
  expect(await a.query(api.push.configuration, {})).toBeNull();
  expect(await a.query(api.calls.get, { id: callId })).toBeNull();
  expect(await a.query(api.calls.signals, { id: callId, session: "owner-session" })).toEqual([]);
  expect(await b.query(api.calls.current, {})).toBeNull();
});
